package com.gathin.tvhome;
import android.animation.ValueAnimator;
import android.content.Context;
import android.graphics.*;
import android.text.*;
import android.view.View;
import android.view.animation.LinearInterpolator;
import java.util.*;
/** Bounded square particles run only during a transition; the resting view is one cached bitmap. */
final class QuoteWidgetView extends View {
    private final QuoteParticleLayers layers;private String enterPath="widget",exitPath="widget";private boolean enterFront,exitFront;
    private final Paint paint=new Paint(3);private final TextPaint textPaint=new TextPaint(3);private Bitmap current,old;private QuoteFeed.State data;private String mode="text",effect="fade",font="default",signature="";private int size=23,ink=Color.WHITE;private boolean active;private float progress=1;private ValueAnimator animation;
    private final List<Pixel> incoming=new ArrayList<>(),outgoing=new ArrayList<>();
    private static final class Pixel {float x,y,drift,delay,fall;int color;Pixel(float x,float y,int color,Random r,float h){this.x=x;this.y=y;this.color=color;drift=(r.nextFloat()-.5f)*h*.25f;delay=r.nextFloat()*.22f;fall=h*(.8f+r.nextFloat()*.7f);}}
    QuoteWidgetView(Context c,QuoteParticleLayers layers){super(c);this.layers=layers;layers.register(this);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);setFocusable(false);}
    void style(HomeWidgetStore.Spec s,int ink){String next=s.quoteMode+"|"+s.quoteEffect+"|"+s.quoteFont+"|"+s.quoteSize+"|"+ink+"|"+s.quoteEnterPath+"|"+s.quoteExitPath+"|"+s.quoteEnterFront+"|"+s.quoteExitFront;if(signature.equals(next))return;signature=next;mode=s.quoteMode;effect=s.quoteEffect;font=s.quoteFont;size=s.quoteSize;this.ink=ink;enterPath=s.quoteEnterPath;exitPath=s.quoteExitPath;enterFront=s.quoteEnterFront;exitFront=s.quoteExitFront;render(false);}
    void data(QuoteFeed.State next){boolean changed=data==null||!data.text.equals(next.text)||!data.note.equals(next.note)||data.image!=next.image;data=next;setContentDescription("Spruch des Tages · "+(next.text.isEmpty()?next.note:next.text));if(changed||current==null)render(changed);}
    void active(boolean on){active=on;if(!on)finish();}
    void preview(){if(current!=null&&active)transition(current);}
    @Override protected void onSizeChanged(int w,int h,int ow,int oh){render(false);}
    private void render(boolean animate){if(getWidth()<1||getHeight()<1)return;Bitmap next=Bitmap.createBitmap(getWidth(),getHeight(),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(next);float d=getResources().getDisplayMetrics().density;int available=Math.max(1,getHeight());String text=data==null||data.text.isEmpty()?data!=null&&!data.note.isEmpty()?data.note:"Spruch wird geladen …":data.text;
        if("image".equals(mode)&&data!=null&&data.image!=null){float scale=Math.min(getWidth()/(float)data.image.getWidth(),available/(float)data.image.getHeight());float w=data.image.getWidth()*scale,h=data.image.getHeight()*scale;paint.setAlpha(255);c.drawBitmap(data.image,null,new RectF((getWidth()-w)/2,(available-h)/2,(getWidth()+w)/2,(available+h)/2),paint);}
        else {textPaint.setTypeface(Typography.face(getContext(),font,R.string.font_medium));textPaint.setColor(ink);textPaint.setTextSize(size*getResources().getDisplayMetrics().scaledDensity);StaticLayout layout=layout(text,getWidth());while(layout.getHeight()>available&&textPaint.getTextSize()>10*d){textPaint.setTextSize(textPaint.getTextSize()-d);layout=layout(text,getWidth());}if(layout.getHeight()>available)layout=StaticLayout.Builder.obtain(text,0,text.length(),textPaint,getWidth()).setAlignment(Layout.Alignment.ALIGN_NORMAL).setIncludePad(false).setLineSpacing(0,1.13f).setEllipsize(TextUtils.TruncateAt.END).setMaxLines(Math.max(1,(int)(available/(textPaint.getFontSpacing()*1.13f)))).build();c.save();c.clipRect(0,0,getWidth(),available);c.translate(0,Math.max(0,(available-layout.getHeight())/2f));layout.draw(c);c.restore();}
        if(animate&&active&&!"none".equals(effect))transition(next);else{finish();current=next;redraw();}}
    private StaticLayout layout(String text,int width){return StaticLayout.Builder.obtain(text,0,text.length(),textPaint,Math.max(1,width)).setAlignment(Layout.Alignment.ALIGN_NORMAL).setIncludePad(false).setLineSpacing(0,1.13f).build();}
    private void transition(Bitmap next){finish();old=current;current=next;progress=0;if("pixels".equals(effect)&&"text".equals(mode)){sample(old,outgoing,91);sample(current,incoming,73);}animation=ValueAnimator.ofFloat(0,1);animation.setInterpolator(new LinearInterpolator());animation.setDuration("pixels".equals(effect)&&"text".equals(mode)?("screen".equals(enterPath)||"screen".equals(exitPath)?3600:2600):1400);animation.addUpdateListener(v->{progress=(float)v.getAnimatedValue();if(progress>=1){old=null;incoming.clear();outgoing.clear();}redraw();});animation.start();}
    private void sample(Bitmap bitmap,List<Pixel> pixels,long seed){pixels.clear();if(bitmap==null)return;Random r=new Random(seed);int step=Math.max(2,Math.round(getResources().getDisplayMetrics().density*1.5f)),seen=0;for(int y=step/2;y<bitmap.getHeight();y+=step)for(int x=step/2;x<bitmap.getWidth();x+=step){int color=bitmap.getPixel(x,y);if(Color.alpha(color)<=80)continue;Pixel pixel=new Pixel(x,y,color,r,getHeight());if(pixels.size()<1800)pixels.add(pixel);else{int at=r.nextInt(++seen+1800);if(at<1800)pixels.set(at,pixel);}}}
    private void particles(Canvas c,List<Pixel> pixels,boolean entering,float t){float block=Math.max(2,getResources().getDisplayMetrics().density*1.4f);boolean screen="screen".equals(entering?enterPath:exitPath);float origin=screen?layers.originY(this):0,height=layers.height();for(Pixel p:pixels){float q=Math.max(0,Math.min(1,(t-p.delay)/.78f)),ease=1-(1-q)*(1-q)*(1-q);float x=entering?p.x+p.drift*(1-ease):p.x+p.drift*q;float y=screen?(entering?QuoteMotion.enter(p.y,origin,height,p.fall*.2f,q):QuoteMotion.exit(p.y,origin,height,p.fall*.2f,q)):entering?p.y-p.fall*(1-ease):p.y+p.fall*q*q;paint.setColor(p.color);paint.setAlpha(Math.round(Color.alpha(p.color)*QuoteMotion.alpha(entering,screen,q)));c.drawRect(x-block/2,y-block/2,x+block/2,y+block/2,paint);}}
    boolean external(boolean front){return active&&isShown()&&animation!=null&&progress<1&&"pixels".equals(effect)&&"text".equals(mode)&&("screen".equals(enterPath)&&enterFront==front||"screen".equals(exitPath)&&exitFront==front);}
    void drawExternal(Canvas c,boolean front){if(progress<.48f&&"screen".equals(exitPath)&&exitFront==front)particles(c,outgoing,false,progress/.48f);if(progress>.22f&&"screen".equals(enterPath)&&enterFront==front)particles(c,incoming,true,(progress-.22f)/.78f);}
    private void redraw(){invalidate();layers.invalidate();}
    @Override protected void onDraw(Canvas c){super.onDraw(c);if(current==null)return;if(progress<1&&"pixels".equals(effect)&&"text".equals(mode)){if(old!=null&&progress<.18f){paint.setColor(Color.WHITE);paint.setAlpha(Math.round(255*(1-progress/.18f)));c.drawBitmap(old,0,0,paint);}if(progress<.48f)particles(c,outgoing,false,progress/.48f);if(progress>.22f)particles(c,incoming,true,(progress-.22f)/.78f);if(progress>.72f){paint.setColor(Color.WHITE);paint.setAlpha(Math.round(255*(progress-.72f)/.28f));c.drawBitmap(current,0,0,paint);}return;}paint.setColor(Color.WHITE);if(old!=null&&progress<1){paint.setAlpha(Math.round(255*(1-progress)));c.drawBitmap(old,0,0,paint);}paint.setAlpha(Math.round(255*progress));c.drawBitmap(current,0,0,paint);paint.setAlpha(255);}
    private void finish(){if(animation!=null){animation.cancel();animation=null;}progress=1;old=null;incoming.clear();outgoing.clear();redraw();}
    void close(){finish();layers.unregister(this);current=null;data=null;}
    @Override protected void onDetachedFromWindow(){finish();super.onDetachedFromWindow();}
}
